import re

# Let's first check for apologies in agent responses
# An apology from the support agent would contain words like "sorry", "apologize", "apologies"
apology_patterns = re.compile(r'\b(sorry|apologize|apologies|apology|apologise)\b', re.IGNORECASE)

# For each company, let's check how many dialogs have apologies from the agent
company_apology_stats = {}

for company in companies:
    company_dialogs = [d for d in dataset if d['company_id'] == company]
    dialogs_with_apology = 0

    for d in company_dialogs:
        dialog_text = d['dialog']
        # Extract agent messages (lines starting with the company name)
        agent_messages = []
        for line in dialog_text.split('\n\n'):
            if line.strip().startswith(company):
                agent_messages.append(line)

        agent_text = ' '.join(agent_messages)
        if apology_patterns.search(agent_text):
            dialogs_with_apology += 1

    company_apology_stats[company] = {
        'total': len(company_dialogs),
        'with_apology': dialogs_with_apology,
        'apology_rate': dialogs_with_apology / len(company_dialogs) if company_dialogs else 0
    }

print("Apology stats per company (in ALL dialogs):")
for company, stats in sorted(company_apology_stats.items(), key=lambda x: x[1]['apology_rate'], reverse=True):
    print(f"  {company}: {stats['with_apology']}/{stats['total']} = {stats['apology_rate']:.2%}")

# Strategy: For each company, identify dialogs WITHOUT apologies
# Then use LLM to check if those dialogs are complaints
# If a company has NO complaint dialogs without apology, it qualifies

# Let's gather non-apology dialogs for each company
company_no_apology = {}
for company in companies:
    company_dialogs = [d for d in dataset if d['company_id'] == company]
    no_apology = []
    for d in company_dialogs:
        dialog_text = d['dialog']
        agent_messages = []
        for line in dialog_text.split('\n\n'):
            if line.strip().startswith(company):
                agent_messages.append(line)
        agent_text = ' '.join(agent_messages)
        if not apology_patterns.search(agent_text):
            no_apology.append(d)
    company_no_apology[company] = no_apology

print("Dialogs WITHOUT apology per company:")
for company in sorted(company_no_apology.keys(), key=lambda x: len(company_no_apology[x])):
    print(f"  {company}: {len(company_no_apology[company])} dialogs without apology")

